	}
}

::view-transition-old(astro-dev-toolbar),
::view-transition-new(astro-dev-toolbar) {
	animation: none;
}

#dev-toolbar-root {
	position: fixed;
	bottom: 0px;
	z-index: 2000000010;
	display: flex;
	flex-direction: column;
