	opacity: 0.2;
}

#dev-toolbar-root[data-placement="bottom-left"] {
	left: 16px;
}
#dev-toolbar-root[data-placement="bottom-center"] {
	left: 50%;
	transform: translateX(-50%);
}
#dev-toolbar-root[data-placement="bottom-right"] {
	right: 16px;
}

