}

#dev-bar .item .icon {
	position: relative;
	max-width: 20px;
	max-height: 20px;
	user-select: none;
}

#dev-bar .item .icon>svg {
	width: 20px;
	height: 20px;
	display: block;
	margin: auto;
}

@media (forced-colors: active) {
	#dev-bar .item svg path[fill="#fff"] {
		fill: black;
	}
}

#dev-bar .item .notification {
	display: none;
	position: absolute;
	top: -4px;
	right: -6px;
	width: 10px;
	height: 10px;
}

#dev-bar .item .notification svg {
	display: block;
}

#dev-toolbar-root:not([data-no-notification]) #dev-bar .item .notification[data-active] {
	display: block;
}

#dev-bar #bar-container {
	height: 100%;
	display: flex;
}

#dev-bar .separator {
	background: rgba(52, 56, 65, 1);
	width: 1px;
